private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);



            if (GetCurrentColumnValue("KODI") != null)
            {
                   xrTableCell1.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('RaportiShpejte.aspx?scopeID=" + parametraRaporti.ScopeID+ "&guidString=" + parametraRaporti.GuidString+ "&idraporti=" + parametraRaporti.IdSubRaporti + "&filterKartela=" + GetCurrentColumnValue("KODI") + "&printo=0&Sesioni=true')";
                    xrTableCell1.Target = "_self";

            }

}

