int row = 0;
private void GroupHeader4_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (row % 2 == 0)
                GroupHeader4.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportEven"];
            else
                GroupHeader4.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportOdd"];
            row++;
}

